import"./chunk-2NFLSA4Y.js";var o={lunarMission:{theory:{concept:"[[A flight to the Moon is a sequence of orbits joined by short engine burns: with its engines off a spacecraft moves under gravity alone, and only a burn that changes its speed can change its orbit.]]"},section:{tli:{title:"Translunar injection",text:"In a parking orbit 185 km up the spacecraft moves at about 7.8 km/s. TLI adds about 3.1 km/s in a few minutes of engine firing. That is just under the escape velocity (about 11 km/s there), so the orbit becomes a very long ellipse whose far end reaches the Moon, about 384 000 km away. The trip takes about three days."},timing:{title:"Aim where the Moon will be",text:"[[The Moon moves about 13\xB0 along its orbit every day, so the spacecraft must aim where the Moon will be when it arrives, not where it is now.]] The burn is made when the Moon is a certain angle ahead (the phase angle). A small change of the angle or of the burn decides between hitting the Moon, swinging round it or missing it completely."},freeReturn:{title:"Free return: home without an engine",text:"[[On a free-return path the spacecraft passes behind the Moon, and the Moon's gravity turns it back towards the Earth.]] Seen from a frame that turns with the Moon, the path looks like a figure eight. It is a safety choice: if the main engine fails, the crew still come home. Apollo 13 used it in 1970 after an oxygen tank exploded; the crew passed about 250 km above the far side and came back safely."},artemis:{title:"Artemis",text:"Artemis I (2022, uncrewed) flew Orion into a wide orbit around the Moon and back. Artemis II, the first crewed flight to the Moon since Apollo 17 in 1972, flew a free-return path in April 2026: after checking the spacecraft in orbit around the Earth, Orion fired its engine for TLI, swung around the far side about 6 500 km above the surface and came home ten days after launch. Its four astronauts went farther from the Earth than anyone before \u2014 about 406 800 km, beating the record of Apollo 13."},apollo11:{title:"Staying at the Moon: Apollo 11",text:"To land, Apollo 11 (1969) needed more burns. Near the closest point to the Moon, lunar orbit insertion (LOI) slowed the spacecraft by about 0.9 km/s so the Moon captured it. After the landing and many orbits, trans-Earth injection (TEI) added about 1 km/s on the far side and sent the crew home."},frames:{title:"Two ways to look",text:"Seen from space, the Earth stays still and the Moon moves round; the path is a long loop. Seen from a frame that turns with the Moon, the Earth and the Moon both stay still, and the free return becomes the famous figure eight. It is the same motion \u2014 only the point of view changes."},check:{title:"Check your understanding",text:"Why is TLI almost as big as the escape velocity? What happens if the burn is too small? Why does a free-return path pass behind the Moon? Why must the spacecraft aim ahead of the Moon? Try each answer in the simulation."}},formula:{tli:"TLI: from circular speed almost to escape speed",circular:"Circular speed at distance r",hohmann:"Slowest (Hohmann) transfer time to the Moon's distance; faster paths take about 3 days",threeBody:"Acceleration from the Earth and the Moon (restricted three-body problem)"},variable:{dv:"Change of speed in an engine burn",r:"Distance from the Earth's centre",phase:"How far the Moon is ahead at TLI",a:"Semi-major axis of the transfer ellipse"},assumption:{plane:"Everything moves in one plane; the Moon's orbit is a circle; the Sun's pull is ignored.",burns:"Engine burns are instant. Real ones last minutes (TLI about 6 min).",corrections:"Real missions make small correction burns on the way; they are not simulated.",parking:"All missions start from a 185 km circular parking orbit (Artemis II really started from a higher orbit).",scale:"Earth and Moon are drawn to scale but never smaller than a few pixels; zoom in to see the closest approach."},param:{mission:"Mission",tliDv:"TLI burn",phase:"Moon ahead at TLI",loi:"Brake into lunar orbit (LOI)",timeScale:"Time speed-up \xD7"},hint:{mission:"Real flights, or your own trajectory.",tliDv:"About 3 150 m/s reaches the Moon. Less falls back, more flies past.",phase:"The angle by which the Moon leads the spacecraft when the engine fires.",loi:"At the closest point to the Moon, brake into a circular orbit around it.",timeScale:"How many seconds of flight pass in one second of animation."},preset:{artemis2:"Artemis II \u2014 free return",apollo13:"Apollo 13 \u2014 free return, close pass",apollo11:"Apollo 11 \u2014 lunar orbit and return",custom:"Custom trajectory"},measure:{flightTime:"Flight time",earthDistance:"Distance from the Earth",moonDistance:"Distance from the Moon",speed:"Speed relative to the Earth",closestMoon:"Closest to the Moon's surface",farthestEarth:"Farthest from the Earth",tliDv:"TLI burn",moonSpeed:"Speed relative to the Moon",totalDv:"Total of all burns"},view:{earth:"Earth",moon:"Moon",tli:"TLI",loi:"LOI",tei:"TEI",day:"Day {day}",parking:"Parking orbit around the Earth",outbound:"On the way to the Moon",return:"On the way home",lunarOrbit:"In lunar orbit \xB7 {orbits} orbits",done:"Mission over",returned:"Back home after {days} days",lunarImpact:"Crashed on the Moon",escaped:"Lost in space",timeout:"Still out there after 16 days",rotatingOption:"Turn with the Moon",markersOption:"Engine burns and Moon orbit"},graph:{distance:"Distances against time",speed:"Speed against time"},challenge:{beyond:{title:"Farther than the Moon",description:"Fly a mission that goes more than 390 000 km from the Earth and comes back.",hint:"A free return swings round the far side of the Moon. Try Artemis II."},apollo11:{title:"Land and return",description:"Fly a mission that orbits the Moon and returns to the Earth.",hint:"Apollo 11 brakes into lunar orbit and later fires its engine again to come home."},tooSlow:{title:"Not enough",description:"Design a trajectory whose TLI is too small to reach the Moon.",hint:"Choose \u201CMy trajectory\u201D and lower the TLI burn below about 3 050 m/s."},ownFreeReturn:{title:"My free return",description:"Find your own free-return trajectory: round the Moon (closer than 20 000 km) and back, without braking.",hint:"Start from about 3 150 m/s and 126\xB0, then change one value at a time in small steps."},impact:{title:"Hit the Moon",description:"Aim so precisely that the spacecraft hits the Moon \u2014 like many robotic probes did.",hint:"Change the Moon angle in small steps until the closest approach drops to zero."},stay:{title:"Stay at the Moon",description:"With your own trajectory, brake into lunar orbit and stay for at least 10 orbits.",hint:"Turn on LOI and choose a path that passes close to the Moon."}}}},a={sim:o};export{a as default,o as sim};
